-- The pace tags of exercises.sql, by name, for a database seeded without them.

INSERT OR IGNORE INTO tag (name, is_system) SELECT 'SPEED', 1 WHERE EXISTS (SELECT 1 FROM exercise e WHERE e.is_custom = 0 AND e.name IN ('Bicycling', 'Bicycling, Stationary', 'Recumbent Bike', 'Rowing, Stationary', 'Skating'));
INSERT OR IGNORE INTO exercise_tag (exercise_id, tag_id) SELECT e.id, t.id FROM exercise e JOIN tag t ON t.name = 'SPEED' WHERE e.is_custom = 0 AND e.name IN ('Bicycling', 'Bicycling, Stationary', 'Recumbent Bike', 'Rowing, Stationary', 'Skating');
